import{_ as o,o as e,c as a,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Sketch-based Fluid Video Generation Using Motion-Guided Diffusion Models in Still Landscape Images","description":"","frontmatter":{"title":"Sketch-based Fluid Video Generation Using Motion-Guided Diffusion Models in Still Landscape Images","arxiv":"2510.15874","date":"2025-07-15","authors":"Hao Jin, Haoran Xie","categories":"cs.GR","topics":"物理感知视频生成, 流体动画, 草图控制","outline":[2,2]},"headers":[],"relativePath":"papers/2510.15874.md","filePath":"papers/2510.15874.md","lastUpdated":null}'),n={name:"papers/2510.15874.md"};function i(s,t,l,d,g,u){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="sketch-based-fluid-video-generation-using-motion-guided-diffusion-models-in-still-landscape-images" tabindex="-1">Sketch-based Fluid Video Generation Using Motion-Guided Diffusion Models in Still Landscape Images <a class="header-anchor" href="#sketch-based-fluid-video-generation-using-motion-guided-diffusion-models-in-still-landscape-images" aria-label="Permalink to &quot;Sketch-based Fluid Video Generation Using Motion-Guided Diffusion Models in Still Landscape Images&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2510.15874" target="_blank" rel="noreferrer">2510.15874</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-15</td></tr><tr><td><strong>作者</strong></td><td>Hao Jin, Haoran Xie</td></tr><tr><td><strong>分类</strong></td><td>cs.GR</td></tr><tr><td><strong>一句话</strong></td><td>把手绘运动草图先扩散成一张彩色编码的运动场图像，再用 motion adapter 把这张单帧运动场注入视频扩散模型的时序层，让静态风景照里的瀑布河流按用户笔迹流动。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>给一张静态风景照配上流动的水，是 cinemagraph 这类创作里最常见也最难自动化的需求。难点不在于&quot;让像素动起来&quot;，而在于让水按创作者想要的方向、速度和分叉去流。论文明确点出两条既有路线各自的死角：物理仿真方法逐粒子追踪流体，结果对边界条件极其敏感，一张任意构图的风景照根本给不出干净的边界；latent diffusion 类视频生成模型能产出高保真、时序连贯的画面，但把流体动得<strong>平滑且时序一致</strong>依然困难，更别说让用户精确指定&quot;这条瀑布往左偏、那段河面往右卷&quot;。</p><p>这篇 SIGGRAPH 2025 Poster 的定位很清楚：把控制信号从文本/轨迹换成<strong>手绘运动草图</strong>，并给出一条足够轻的两阶段流水线。价值在于交互效率——草图是创作者最自然的表达媒介，比调 prompt 或拖轨迹点更接近&quot;直接画出我要的水流&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文点名的前人工作只有四组，但每一组都对应一个具体缺口。</p><p>Holynski 等人 2021 年的 <em>Animating Pictures with Eulerian Motion Fields</em> 提供了本文使用的风景数据集与&quot;用运动场驱动静态图&quot;的范式，它直接预测运动场本身；本文指出这样做的训练时间与算力开销都更重，且细节保留不好。MotionCtrl（Wang et al., 2024）是运动可控视频生成的代表，但它需要<strong>一整个运动场序列</strong>作为条件，条件构造成本高。Sketch2Cinemagraph（Jin et al., 2024，同一作者组的前作）给出了&quot;用 ControlNet 从草图生成运动场&quot;的思路，本文承认自己受其启发，属于在其上做视频扩散端的延伸。Stable Video Diffusion 作为通用 I2V baseline，缺的是任何形式的运动方向控制。</p><p>需要说明的是，这是一篇两页 poster，它没有系统梳理流体视频生成的整个文献版图，也没有解释&quot;为什么之前没人用单帧运动场&quot;这类更深的问题——<strong>这是篇幅所限，不是论证完备</strong>。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不用本文结论，只用 2024 年底已有的材料，一条自然的推演是这样的：</p><p>第一步，接受&quot;运动场是静态图动画化的正确中间表示&quot;这个 2021 年就被确立的前提。第二步，观察到直接回归运动场的训练很贵——运动场是二通道连续值场，和图像扩散模型预训练的三通道 RGB 分布不匹配，等于放弃了所有预训练先验。这时一个很自然的念头是：<strong>把运动场画成一张图</strong>（用颜色编码方向与幅度，正是光流可视化的标准做法），那么&quot;生成运动场&quot;就退化成&quot;生成图像&quot;，ControlNet + latent diffusion 的整套现成基建可以直接复用。</p><p>第三步，考虑如何把运动场喂给视频模型。MotionCtrl 的做法是每帧一个场，代价是条件序列本身要么来自真实光流、要么要再训一个序列生成器。这时如果你观察过瀑布、河流的真实录像，会发现一个经验事实：<strong>流体的运动模式在时间上高度稳定</strong>——水一直往下落，河一直往同一方向流，逐帧的运动场差异远小于刚体运动。既然如此，一张场就够了。这个观察正是论文给出的动机。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>流体动画的控制信号不需要逐帧给：真实的水流在一段短视频里运动模式几乎不变，所以一张静态的运动场就编码了它的主要动力学。而这张运动场本身，与其当成一个奇怪的回归目标去学，不如<strong>画成一张彩色图片</strong>，让预训练的图像扩散模型来生成它。两个&quot;降维&quot;叠在一起，把一个昂贵的时序控制问题压成了一次图像生成加一次条件注入。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一张含瀑布的风景照为例：</p><ul><li><strong>输入</strong>：一张静态风景图作为 reference image；用户在图上画若干条渐变灰度线条（gradient gray lines）表示希望水流走的路径；可选的文本描述。草图被刻意设计成渐变灰线，是为了和风景数据集里从真值运动场提取出的 streamlines 在外观上对齐。</li><li><strong>阶段一 · 运动场估计</strong>：一个 ControlNet 在草图 + 文本条件下驱动 latent diffusion，输出运动场的<strong>彩色表示</strong>而非运动场数值本身。论文在 Figure 3 中对比了两者，声称彩色版保留了更细的细节，对下游视频生成的引导更有效。把这一步重述成图像生成问题，作者明确 claim 带来了训练时间与算力需求的大幅下降（论文未给具体数字）。</li><li><strong>阶段二 · 运动引导的流体生成</strong>：主干是 LVDM（Latent Video Diffusion Model）。要把一个 text-to-video 主干改造成 image-to-video，做法是把 reference image 的 CLIP embedding 加到起始噪声上，从而锁住首帧内容并促进时空连贯。运动条件通过一个 <strong>motion adapter</strong> 注入：adapter 把彩色运动场编码进 latent 空间，编码后的运动特征被注入去噪 3D U-Net 的 <strong>temporal transformer 层</strong>。注意只用<strong>单张</strong>运动场，不是序列。</li><li><strong>输出</strong>：25 帧、512×320 的流体动画。</li><li><strong>风格外延</strong>：模型只在真实风景数据（Holynski et al., 2021）上训练，但借助扩散模型自带的风格迁移能力，可以直接接受动漫风格的风景图作为 reference，产出既遵循草图运动、又保持动漫画风的视频。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。全文（两页 poster）未给出任何损失函数、采样公式或运动场编码的解析式；彩色运动场的具体编码规则也只以图示说明，未写成公式。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>论文只做了一组定量对比，问题、设计、答案都很短。</p><p><strong>问题</strong>：单帧运动场引导下的流体，比通用 I2V 基线更真实吗？<strong>设计</strong>：与 Stable Video Diffusion 对比，每段视频 25 帧、512×320 分辨率，正文说用 FVD 衡量合成视频与对应真值视频的差距。<strong>答案</strong>：作者 claim 自己的框架产出更真实的流体动力学。这里必须如实说明一个证据缺口——arXiv 的 HTML 版中 Table 1 的<strong>列名未能渲染</strong>，只留下两列数值：SVD 为 0.3508 与 13.2409，Ours 为 0.3049 与 15.6186。正文只提到 FVD，但这两个量级都不像常见的 FVD 取值，因此<strong>无法确认哪一列对应哪个指标</strong>，本文不对指标归属做断言，只记录数值方向：一列越低越好、一列越高越好的话，本文两列都优于 SVD。</p><p>其余结论都是定性的：Figure 4 展示多种流体场景下的生成帧，作者认为框架能处理复杂运动模式；动漫风格结果显示生成流体既贴合草图引导，又在整个帧序列中保持画风一致。没有 ablation，没有与 MotionCtrl 或 Sketch2Cinemagraph 的直接对比，也没有用户研究。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：论文用手绘运动草图控制静态风景照中的流体动画。第一阶段用 ControlNet 条件化的 latent diffusion，从草图生成运动场的<strong>彩色图像表示</strong>，从而把运动场估计降级成一次普通的图像生成，省下训练开销。第二阶段用 motion adapter 把这张彩色运动场编码进 latent 空间，注入 LVDM 去噪 3D U-Net 的 temporal transformer 层，同时靠 reference image 的 CLIP embedding 加在起始噪声上完成 T2V→I2V 改造。关键的方法学赌注是<strong>只用一张运动场而非序列</strong>，理由是真实流体运动在时间上高度稳定。与 SVD 的对比显示了数值优势，但 HTML 版表格列名缺失，且没有消融。</p><p><strong>3 句话版</strong>：把运动场画成彩色图片，用图像扩散模型生成它；再用单张运动场经 adapter 注入视频扩散模型的时序层。核心假设是流体运动的时序稳定性使单帧条件足够。SIGGRAPH 2025 Poster，两页篇幅，实验只有一组与 SVD 的对比。</p><p><strong>1 句话版</strong>：用一张&quot;画出来的&quot;运动场，把草图变成风景照里可控的水流。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是<strong>单张运动场足以刻画整段视频的流体动力学</strong>。论文给的理由是&quot;real-world fluid motion typically exhibits strong temporal stability&quot;，这在瀑布、平稳河流、海面这类<strong>准稳态</strong>流动上大致成立，但它恰好排除了流体最有表现力的那一类：破碎的浪、涌起的漩涡、被风改变方向的水幕、水与岩石碰撞后的溅射。这些场景的运动场随时间显著变化，单帧条件在物理上无法表达。</p><p>论文为这个假设提供的证据是<strong>间接的</strong>：数据集来自 Holynski 等人的风景视频，本身就以稳态流体为主；定量对比只在这一分布上做。也就是说，训练与评测都发生在假设成立的区域内，论文没有给出任何在非稳态流体上的失败案例或压力测试。如果假设不成立，方法退化的方式是可预测的：生成的水会保持一个僵硬不变的流向，看起来像循环贴图而非真实流体。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要复现完整系统：</p><ol><li><strong>取现成的 I2V 模型</strong>（SVD 或任一开源 LVDM），不训练它。</li><li><strong>构造条件对照</strong>：在 Holynski 风景数据集上，用光流估计器（RAFT 即可）抽出每段视频的逐帧光流。构造两种条件——(a) 首帧光流复制 T 次，(b) 真实的逐帧光流序列。</li><li><strong>只训练 adapter</strong>：冻结主干，分别用 (a) 和 (b) 训练同架构的 motion adapter，训练步数与超参完全一致。</li><li><strong>测量</strong>：在测试集上比较两者的 FVD 与&quot;运动方向一致性&quot;（生成视频的估计光流与真值光流的逐帧余弦相似度随 t 的衰减曲线）。</li><li><strong>判据</strong>：若 (a) 与 (b) 的差距在稳态流体子集上小于 5%、在非稳态子集（人工挑出含碎浪/漩涡的片段）上大于 20%，则<strong>支持</strong>论文的核心假设同时<strong>界定</strong>了它的适用边界；若两个子集上差距都很小，说明单帧条件的近似性比论文宣称的还要宽；若稳态子集上差距就很大，则直接反驳。</li></ol><p>这个实验不需要复现 ControlNet 草图分支，因为要检验的假设只关于&quot;单帧 vs 序列&quot;。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是给出一个<strong>替代解释</strong>：本文相对 SVD 的数值优势，可能主要来自&quot;有条件 vs 无条件&quot;，而与&quot;彩色运动场&quot;这个具体表示形式无关。SVD 在这个任务上完全没有运动方向信息，它必须靠先验去猜水往哪流；任何合理的运动条件——原始二通道光流张量、稀疏轨迹点、甚至一张二值 mask 加一个方向角——都会带来大幅改善。论文没有做&quot;彩色运动场 vs 直接运动场&quot;的<strong>下游视频质量</strong>消融（Figure 3 只对比了运动场本身的视觉细节），因此&quot;彩色表示更有效&quot;这一 claim 在下游任务上是未经检验的。</p><p>一个可预测的失败场景：让用户画一条<strong>与训练分布不符</strong>的草图，例如让瀑布向上流、或让河水在画面中央做环形运动。由于运动场生成器是在从真实风景光流提取的 streamlines 上训练的，它很可能把这类草图&quot;修正&quot;回训练分布中最接近的合理流向，从而暴露出这个 pipeline 的控制其实是<strong>软的、被先验主导的</strong>，而非论文所称的 &quot;precisely control the fluid movement&quot;。论文没有展示任何反直觉草图的结果。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>一个非增量的重构：<strong>不要把运动场当条件，把它当作可微的中间变量，并让物理约束作用在它身上</strong>。</p><p>(a) <strong>驱动的局限</strong>：本文的运动场是一次性生成、之后固定不变的开环条件；它既不保证无散度（不可压缩流体的基本约束），也不保证与生成视频真实呈现的运动一致。用户画得再准，也没有任何机制保证输出视频的光流真的等于那张运动场。</p><p>(b) <strong>可借鉴的相邻工具</strong>：计算流体动力学里的 <strong>Helmholtz 分解</strong>与 physics-informed neural networks。把生成的运动场投影到无散度子空间（一次 Poisson 求解，可微），即可让草图输入自动获得&quot;物理上可实现&quot;的修正；同时把去噪过程中估计出的视频光流与目标运动场之间的差作为 guidance 梯度回注采样（类似 classifier guidance），构成闭环。</p><p>(c) <strong>第一个实验</strong>：在同一 LVDM 主干上做三档对比——开环单帧条件（本文）、加无散度投影、加投影且加光流闭环 guidance。测量指标不再是 FVD，而是<strong>控制保真度</strong>：生成视频估计光流与用户草图诱导运动场的角度误差随帧号的变化曲线。如果闭环版本能把误差在 25 帧内维持在一个平台而开环版本单调发散，就说明&quot;运动条件应该是被约束和被校验的物理量，而不是一张被扔进 adapter 的图片&quot;。这一 framing 也自然把方法从流体推广到任何有守恒律可写的运动介质（烟、云、织物）。</p>',44)])])}const c=o(n,[["render",i]]);export{h as __pageData,c as default};
